// handleCloseParlay closes (settles out) a paper parlay at its CURRENT live mark, booking the P&L
// (audit #9: the old close recorded nothing — no payout, no realized, no timestamp).
func (s *Server) handleCloseParlay(w http.ResponseWriter, r *http.Request) {
	var req struct {
		ID int64 `json:"id"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid JSON body"})
		return
	}
	ctx := r.Context()
	open, _ := s.store.ListParlays(ctx, "open")
	var target *paper.Parlay
	for i := range open {
		if open[i].ID == req.ID {
			target = &open[i]
			break
		}
	}
	if target == nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "combo not open (already settled/closed?)"})
		return
	}
	// Mark each leg from the live book; a leg with no live price falls back to entry (conservative flat).
	mark := 1.0
	for _, lg := range target.Legs {
		if px, ok := s.parlayLiveLegPrice(ctx, lg); ok {
			mark *= px
		} else {
			mark *= lg.Entry
		}
	}
	exitFee := 0.07 * target.Contracts * mark * (1 - mark)
	realized := target.Contracts*mark - target.Stake - target.Fees - exitFee
	changed, err := s.store.CloseParlayIfOpen(ctx, req.ID, mark, realized)
	if err != nil {
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}
	if !changed {
		writeJSON(w, http.StatusConflict, map[string]string{"error": "combo became terminal before this close"})
		return
	}
	_ = s.store.Audit(ctx, "info", "parlay", fmt.Sprintf("combo #%d manually closed @ mark %.3f: realized %+.2f", req.ID, mark, realized), "")
	writeJSON(w, http.StatusOK, map[string]any{"ok": true, "mark": mark, "realized": realized})
}

var crossStop = map[string]bool{"will": true, "the": true, "win": true, "match": true, "game": true,
	"price": true, "winner": true, "wins": true, "before": true, "after": true, "with": true,
	"from": true, "and": true, "for": true, "who": true, "what": true, "this": true, "that": true,
	"year": true, "next": true, "your": true, "above": true, "below": true, "reach": true,
	"close": true, "hit": true, "vs": true}

// tokenAlias canonicalizes cross-venue spelling differences so the SAME real-world entity
// tokenizes identically on Kalshi and Polymarket — the #1 reason equivalent markets failed to
// pair. Short aliases (len<4) are captured here even though raw short tokens are otherwise
// dropped: that's how "btc" (3 chars) becomes the distinctive token "bitcoin". Crypto majors
// are the highest-value case because the same coin re-lists every 15m/hour on both venues.
var tokenAlias = map[string]string{
	"btc": "bitcoin", "xbt": "bitcoin", "bitcoin": "bitcoin",
	"eth": "ethereum", "ether": "ethereum", "ethereum": "ethereum",
	"sol": "solana", "solana": "solana",
	"xrp": "xrp", "ripple": "xrp",
	"doge": "dogecoin", "dogecoin": "dogecoin",
	"ada": "cardano", "cardano": "cardano",
	"bnb": "binance", "ltc": "litecoin", "litecoin": "litecoin",
	"link": "chainlink", "chainlink": "chainlink",
	"avax": "avalanche", "avalanche": "avalanche", "matic": "polygon",
}

func sigTokens(s string) map[string]bool {
	out := map[string]bool{}
	var cur []rune
	flush := func() {
		if len(cur) == 0 {
			return
		}
		w := strings.ToLower(string(cur))
		cur = cur[:0]
		if c, ok := tokenAlias[w]; ok { // known alias → canonical token (even if the raw form is short, e.g. "btc")
			out[c] = true
			return
		}
		if len(w) >= 4 && !crossStop[w] {
			out[w] = true
		}
	}
	for _, r := range s {
		if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') {
			cur = append(cur, r)
		} else {
			flush()
		}
	}
	flush()
	return out
}

// crossMatchKalshi finds the Kalshi market whose title best overlaps a Polymarket
// question (>= 2 shared significant words) — a conservative cross-platform match.
// Returns (ticker, title, YES price as a 0–1 FRACTION, ok).
//
// R70 (audit follow-up): this used to return (Title, event URL, ImpliedProbability()*100) — the
// sole caller (sweepSharpline) treated the first value as the TICKER and the price as a 0–1
// fraction, so every sharpline signal logged a title in the ticker column and a 0–100 price that
// always failed the kPx<=0.02||kPx>=0.98 band — sharpline never logged a single usable row. Now
// the ticker/title/fraction contract matches what the caller (and signal_log) actually needs.
//
// R69 (family "sharpline" — the sole caller is sweepSharpline): telemetry + the DATE GUARD the R68
// audit flagged as missing here. Its sibling bestKalshiMatch has always required resolution dates
// within ±14h; this matcher had NO date evidence (a bare question string), so the same two teams'
// NEXT series game could satisfy the token match. The Odds API events carry commence_time, so the
// caller now passes it: when evDateOK AND the Kalshi market has a parseable expected-expiration/
// close time, the pair must sit within the same ±14h window (dateless on either side → guard silent,
// exactly the bestKalshiMatch convention). Misses record "date-gate" only when the rejected candidate
// was accept-worthy on tokens (same probe discipline as bestKalshiMatch), else "no-candidate".
func crossMatchKalshi(question string, kmarkets []kalshi.Market, evDate time.Time, evDateOK bool) (ticker, title string, yesPx float64, ok bool) {
	q := sigTokens(question)
	if len(q) == 0 {
		matchTelemetry("sharpline", question, "", false, "", "no-candidate")
		return "", "", 0, false
	}
	missReason, missSlug := "", ""
	probeLeft := 128
	bestScore, bestRare, bestIdx, secondScore := 0, 0, -1, 0
	for i, m := range kmarkets {
		t := sigTokens(m.Title + " " + m.YesSubTitle)
		if evDateOK { // R69 date guard — score first (tokens already computed), gate before ranking
			if kd, ok := parseTime(firstNonEmpty(m.ExpectedExpiration, m.CloseTime)); ok {
				if d := evDate.Sub(kd); d > 14*time.Hour || d < -14*time.Hour {
					if missReason == "" && probeLeft > 0 {
						probeLeft--
						score, rare := 0, 0
						for w := range q {
							if t[w] {
								score++
								if len(w) >= 6 {
									rare++
								}
							}
						}
						if (score >= 1 && rare >= 1) || score >= 2 {
							missReason, missSlug = "date-gate", m.Ticker
						}
					}
					continue
				}
			}
		}
		score, rare := 0, 0
		for w := range q {
			if t[w] {
				score++
				if len(w) >= 6 { // a distinctive shared token (a name/place), not a common word
					rare++
				}
			}
		}
		if score > bestScore || (score == bestScore && rare > bestRare) {
			secondScore = bestScore // the old best becomes the runner-up
			bestScore, bestRare, bestIdx = score, rare, i
		} else if score > secondScore {
			secondScore = score
		}
	}
	// Match genuinely equivalent events: either 2+ shared significant words (e.g. "Mets" +
	// "Phillies") OR one distinctive token (a 6+ char name/place, e.g. the aliased "bitcoin"),
	// and only when the best STRICTLY beats the runner-up so a coincidental shared name can't
	// pair a tournament-winner market with an unrelated single game. The single-distinctive-token
	// path (with the new ambiguity guard) is what lets cross fire on crypto + named events.
	if bestIdx >= 0 && bestScore > secondScore && ((bestScore >= 1 && bestRare >= 1) || bestScore >= 2) {
		m := kmarkets[bestIdx]
		matchTelemetry("sharpline", question, "", true, m.Ticker, "")
		return m.Ticker, m.Title, m.ImpliedProbability(), true
	}
	if missReason == "" {
		missReason = "no-candidate"
	}
	matchTelemetry("sharpline", question, "", false, missSlug, missReason)
	return "", "", 0, false
}
